import React, { useState, useEffect } from "react";
import {
  useParams,
  useNavigate,
} from "react-router-dom";
import { MapPin, CheckCircle2 } from "lucide-react";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/OrderDetails.css";

export default function OrderDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /orders/:orderId
    setOrder({
      _id: id,
      public_id: "GR-98312",
      status: "preparing",
      status_label: "Being Fulfilled",
      my_role: "payer",
      merchant: {
        _id: "1",
        business_name: "SupaMart Grocers",
        address: "Moi Avenue, Nairobi"
      },
      payer: {
        name: "Ngawang Pema",
        whatsapp_number_masked: "+61 4•• ••• 678"
      },
      recipient: {
        name: "Amina Otieno",
        whatsapp_number_masked: "+254 7•• ••• 678"
      },
      items: [
        {
          product_id: "1",
          name: "Fresh Milk (500ml)",
          unit_label: "500ml bottle",
          product_image: "https://images.unsplash.com/photo-1563636619-e9143da7973b?w=700",
          quantity: 2,
          unit_price: { kes: "57.00", aud: "0.63" },
          line_total: { kes: "114.00", aud: "1.26" }
        },
        {
          product_id: "2",
          name: "Sourdough Artisanal Bread",
          unit_label: "1 loaf",
          product_image: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=700",
          quantity: 1,
          unit_price: { kes: "400.00", aud: "4.43" },
          line_total: { kes: "400.00", aud: "4.43" }
        }
      ],
      item_count: 3,
      subtotal: { kes: "514.00", aud: "5.69" },
      service_charge: { kes: "50.00", aud: "0.55" },
      total: { kes: "564.00", aud: "6.24" },
      fx_rate: "90.30",
      payment: {
        status: "succeeded",
        failure_reason: null,
        paid_at: "2026-10-18T10:30:00.000Z"
      },
      fulfillment: {
        status: "preparing",
        collection_code: "K7M2QD",
        estimated_ready_at: "2026-10-18T11:30:00.000Z",
        fulfilled_at: null
      },
      timeline: [
        { key: "basket_created", label: "Basket Created", state: "done", at: "2026-10-18T10:24:00.000Z" },
        { key: "payment_completed", label: "Payment Completed", state: "done", at: "2026-10-18T10:30:00.000Z" },
        { key: "preparing", label: "Preparing Order", state: "current", at: null },
        { key: "received", label: "Received", state: "upcoming", at: null }
      ],
      actions: {
        can_pay: false,
        can_cancel: false,
        can_mark_received: false
      },
      created_at: "2026-10-18T10:24:00.000Z"
    });
    setLoading(false);
  }, [id]);

  if (loading) {
    return <Screen title="Order Details" back>Loading...</Screen>;
  }

  if (!order) {
    return (
      <Screen title="Order Details" back>
        <p>Order not found.</p>
      </Screen>
    );
  }

  const handleMarkReceived = async () => {
    // TODO: Implement API call to PATCH /orders/:orderId/received
  };

  const formatDate = (dateString) => {
    if (!dateString) return "—";
    const date = new Date(dateString);
    return date.toLocaleString("en-US", { 
      month: "short", 
      day: "numeric",
      hour: "numeric",
      minute: "2-digit"
    });
  };

  return (
    <Screen title="Order Details" back>
      <div className="panel">
        <div className="row between">
          <h3 className="card-title">
            {order.public_id}
          </h3>

          <span
            className={`status ${order.status}`}
          >
            {order.status_label}
          </span>
        </div>

        <p className="muted small">
          {formatDate(order.created_at)}
        </p>
      </div>

      <div className="panel">
        <h3 className="card-title">
          Merchant
        </h3>

        <p>{order.merchant.business_name}</p>

        <p className="muted small row">
          <MapPin size={13} />
          {order.merchant.address}
        </p>
      </div>

      <div className="panel">
        <h3 className="card-title">
          Items
        </h3>

        {order.items.map((item) => (
          <div className="summary-line" key={item.product_id}>
            <span>
              {item.name} × {item.quantity}
            </span>
            <span>KSh {item.line_total.kes}</span>
          </div>
        ))}

        <div className="divider" />

        <div className="summary-line">
          <span>Subtotal</span>
          <span>KSh {order.subtotal.kes}</span>
        </div>

        <div className="summary-line">
          <span>Service charge</span>
          <span>KSh {order.service_charge.kes}</span>
        </div>

        <div className="divider" />

        <div className="summary-line">
          <strong>Total</strong>
          <strong className="orange">
            KSh {order.total.kes}
            <span className="aud-price">≈ AUD {order.total.aud}</span>
          </strong>
        </div>
      </div>

      <div className="panel">
        <h3 className="card-title">
          Order Timeline
        </h3>

        <div className="timeline">
          {order.timeline.map((step, index) => (
            <div key={step.key} className={`timeline-step ${step.state}`}>
              <div className="timeline-marker">
                {step.state === "done" && <CheckCircle2 size={16} />}
                {step.state === "current" && <div className="pulse" />}
                {step.state === "upcoming" && <div className="circle" />}
              </div>
              <div className="timeline-content">
                <strong>{step.label}</strong>
                {step.at && <p className="muted small">{formatDate(step.at)}</p>}
              </div>
            </div>
          ))}
        </div>
      </div>

      {order.fulfillment.collection_code && (
        <div className="panel">
          <h3 className="card-title">
            Collection Code
          </h3>
          <div className="collection-code">
            {order.fulfillment.collection_code}
          </div>
        </div>
      )}

      {order.actions.can_mark_received && (
        <PrimaryButton onClick={handleMarkReceived}>
          Mark as Received
        </PrimaryButton>
      )}
    </Screen>
  );
}
